\section{Appendix: command-line parameters (V51)}
% ======================================================================

Complete list of parameters accepted by \code{compass\_sim} in version V51, extracted directly from the program interface. Parameters marked ``auto'' are calculated from the real physical geometry when omitted and overridden when explicitly supplied.

\begingroup
\small
\setlength{\tabcolsep}{5pt}
\renewcommand{\arraystretch}{1.15}

\begin{longtable}{@{}lll p{7.6cm}@{}}
\caption{Command-line parameters of \code{compass\_sim} V51.}
\label{tab:parametros}\\
\toprule
\textbf{Parameter} & \textbf{Default} & \textbf{Unit} &
\textbf{Description} \\
\midrule
\endfirsthead
\toprule
\textbf{Parameter} & \textbf{Default} & \textbf{Unit} &
\textbf{Description} \\
\midrule
\endhead
\bottomrule
\endlastfoot
\multicolumn{4}{@{}l}{\emph{Lattice geometry}} \\
\midrule
\code{--N} & 8 & --- & Number of needle rows. \\
\code{--M} & 8 & --- & Number of needle columns. \\
\code{--R} & 0.025 & m & Radius of the circle circumscribing each needle; the center-to-center distance between neighbors is $2R$ in all geometries. \\
\code{--needle\_frac} & 0.80 & --- & Needle length as a fraction of the diameter $2R$ (limited to 0--0.8). \\
\code{--geometry} & square & --- & Lattice type: \code{square}, \code{triangular}, or \code{honeycomb}. \\
\midrule
\multicolumn{4}{@{}l}{\emph{Physics and simulation}} \\
\midrule
\code{--moment} & auto & A$\cdot$m$^2$ & Magnetic moment per needle. If omitted: $m = M_s V$, steel saturated along the long axis (uses \code{--steel\_Bsat} and the real volume). \\
\code{--inertia} & auto & kg$\cdot$m$^2$ & Moment of inertia per needle. If omitted: real steel sheet, $I = \tfrac{1}{12}\,\mathrm{mass}\,(L^2 + \mathrm{width}^2)$. \\
\code{--needle\_thickness} & $4 \times 10^{-4}$ & m & Steel-sheet thickness used in both automatic calculations. \\
\code{--steel\_density} & 7850 & kg/m³ & Steel density (automatic inertia calculation). \\
\code{--steel\_Bsat} & 2.0 & T & Saturation flux density of steel (automatic moment calculation; $M_s = B_{\mathrm{sat}}/\mu_0$). Typical range: 1.6--2.2~T. \\
\code{--damping} & $5 \times 10^{-8}$ & N$\cdot$m$\cdot$s/rad & Viscous damping coefficient $b$. Zero = perpetual oscillation. \\
\code{--t\_sim} & 2.0 & s & Total simulated physical time (sum of integrated $\Delta t$ values). \\
\code{--t\_sim\_full} & 0 & --- & 1 = run until the end of \code{t\_sim}, disabling physical early stops ($S{=}1.00$, rest, torque equilibrium); Ctrl+I/Ctrl+C remain active. Useful for uniform-length sweep series. \\
\code{--field\_mode} & static & --- & \code{static}, \code{hysteresis} (five-ramp cycle), \code{sine}, \code{pulse} (wait $\to$ pulse $\to$ stabilization), \code{step\_pos} ($B{=}0$ for \code{field\_delay}, then kept on), or \code{step\_neg} (field from $t{=}0$, removed at \code{field\_delay}). \\
\code{--hyst\_spacing} & linear & --- & Hysteresis-ramp spacing: \code{linear} or \code{log} (log-symmetric through sinh, with small $dB/dt$ near $B{=}0$, fine sampling in the coercivity region, large near $\pm B_{\max}$). \\
\code{--hyst\_log\_k} & 5.0 & --- & Concentration of \code{log} spacing: $k \to 0$ recovers linear; $k{=}5$ concentrates $\sim$15$\times$ more points near $B{=}0$. \\
\code{--field\_delay} & 0.0 & s & Waiting time $\Delta t$: in \code{pulse}, time with $B{=}0$ before the pulse; in \code{step\_pos}, before switching on; in \code{step\_neg}, time with field on before removal. \\
\code{--t\_pulse} & --- & s & Pulse duration (\code{pulse}). If omitted, legacy criterion: field until $S \geq 0.99$ or $S$ plateau. \\
\code{--torque\_tol} & $10^{-3}$ & --- & Relative tolerance of equilibrium criterion in pulse/step modes: stop when $\omega_{\max}$ is small \emph{and} $\langle|\tau|\rangle < \mathrm{tol}\cdot\tau_{\mathrm{ref}}$ ($\tau_{\mathrm{ref}} = I\omega_0^2$) for 50 steps; 0 disables torque criterion. \\
\code{--field\_freq} & 1.0 & Hz & Sinusoidal-field frequency (only \code{sine}). \\
\code{--dt\_factor} & 0.05 & --- & Fraction of natural period $T_0$ used as time step $\Delta t$ (0.02--0.10). \\
\code{--noise} & 1.5 & rad & Initial angular noise amplitude ($0$ = all along $+x$; $\pi$ = fully random). \\
\code{--seed} & 42 & --- & Random-number-generator seed (reproducibility). \\
\code{--pbc} & 0 & --- & Periodic boundary conditions (0/1); with 1, edges interact with replicas through the minimum-image convention. \\
\code{--pbc\_images} & 1 & --- & Replicas summed on each side in each direction when \code{--pbc 1} (default: $3\times3$ cell grid). \\
\code{--gpu} & 0 & --- & GPU backend via CuPy (0/1), with automatic fallback to CPU if unavailable. \\
\code{--progress\_bar} & 1 & --- & Real-time progress bar (0/1); turn off in redirected logs. \\
\code{--halo\_mode} & order & --- & Halo coloring: \code{order} (local alignment) or \code{domains} (connected domains, V38). \\
\code{--domain\_tol} & 15.0 & degrees & Angular tolerance for neighbors to belong to the same domain (\code{--halo\_mode domains}). \\
\midrule
\multicolumn{4}{@{}l}{\emph{Uniform external field}} \\
\midrule
\code{--B\_ext} & 0.0 & T & External-field magnitude (e.g., $50 \times 10^{-6}$ = Earth's field). \\
\code{--phi\_ext} & 0.0 & degrees & Field direction (0 = $+x$, 90 = $+y$, counterclockwise). \\
\code{--ext\_Bx}, \code{--ext\_By} & --- & T & Explicit components; override \code{--B\_ext}/\code{--phi\_ext}. \\
\midrule
\multicolumn{4}{@{}l}{\emph{Output}} \\
\midrule
\code{--video} & --- & --- & Base name of the MP4 video (ffmpeg); automatic numbering \code{name0000.mp4}, \code{0001}, \dots \\
\code{--frame\_every} & 5 & steps & Interval between saved frames. \\
\code{--make\_images} & 1 & --- & 0 = disables \emph{all} PNG generation (frames and summaries), while keeping data CSVs (V39). \\
\code{--fps} & 24 & --- & Video frames per second. \\
\code{--dpi} & 120 & --- & Frame resolution (arrays $>15\times15$: use 150--200). \\
\code{--keep\_frames} & off & --- & Keeps the intermediate PNG folder after MP4 generation. \\
\code{--hyst\_autoscale} & 0 & --- & Enables automatic scaling of the axes in both the live simulation frames (dual panel) and the final hysteresis plots (0/1; V51). \\
\code{--csv\_order} & t & --- & CSV column order: \code{t} $\to$ $t,B,M,S$; \code{B} $\to$ $B,M,S,t$. \\
\end{longtable}
